mapper.select:
		/*selectStockList*/
			WITH mgmtMenuListPage AS(
        SELECT * 
          FROM (
            SELECT * 
              FROM (
                SELECT A.*
                      ,ROWNUM AS RNUM
                  FROM(
						SELECT 
				             TO_NUMBER(STOCK_ID) AS STOCK_ID
				            ,STOCK_CODE
				            ,STOCK_KO_NAME
				            ,STOCK_EN_NAME
				            ,STOCK_COUNTRY_CODE
				            ,STOCK_MARKET
				            ,MARKET_SECTION
				            ,STOCK_TYPE
				            ,STOCK_TYPE_SPECS
				            ,STOCK_SECTOR
				            ,STOCK_ALIASES
				            ,STOCK_URL
				            ,STOCK_DESC
				            ,MODIFY_DATE
				            ,USE_DIV as USE_FLAG
				            ,COUNT(*) OVER() TOTAL_COUNT
						FROM TB_S_INTEREST_STOCK
						WHERE 1=1 
						
						AND STOCK_CODE = #{in_stock_code}
							OR STOCK_ID = #{in_stock_code}
							OR STOCK_KO_NAME like '%' || #{in_stock_code} || '%'
						
						
							AND STOCK_COUNTRY_CODE =  #{in_country}
						
						
							AND USE_DIV =  #{in_useyn}
						
						ORDER BY ${in_column} ${in_order}
                 ) A				
              ) WHERE RNUM <= ${totalPagesize} 
           ) WHERE RNUM > ${currentPageSize}
      )
   SELECT *
     FROM mgmtMenuListPage

mapper.update:
	  UPDATE TB_S_INTEREST_STOCK
          SET USE_DIV = #{use_div}
           ,STOCK_KO_NAME = #{stock_ko_name}
           ,STOCK_EN_NAME = #{stock_en_name}
           ,STOCK_SECTOR = #{stock_sector}
           ,STOCK_MARKET = #{stock_market}
           ,STOCK_COUNTRY_CODE = #{stock_country_code}
           ,STOCK_TYPE = #{stock_type}
           ,STOCK_TYPE_SPECS = #{stock_type_specs}
           ,STOCK_DESC = #{stock_desc}
           ,STOCK_ALIASES = #{stock_aliases}
       WHERE STOCK_CODE = #{stock_code}

	  	UPDATE TB_S_STOCK_ANALYSIS
  		SET USE_DIV = #{use_div}
  		WHERE STOCK_CODE = #{stock_code}

	  	UPDATE TB_S_STOCK_30MINANALYSIS
  		SET USE_DIV = #{use_div}
  		WHERE STOCK_CODE = #{stock_code}

	  	UPDATE TB_S_STOCK_CONSENSUS
  		SET USE_DIV = #{use_div}
  		WHERE STOCK_CODE = #{stock_code}
